contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        // fresh deployment: owner is address(0), which is not this contract,
        // so a non-owner transfer must revert.
        bool reverted;
        try c.transferOwnership(newOwner) { reverted = false; }
        catch { reverted = true; }
        if (reverted) {
            assert(c.owner() != address(this));
        } else {
            assert(c.owner() == newOwner);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        require(newOwner != address(0));
        // fresh deployment: owner is address(0), so msg.sender (this contract) is not the owner.
        bool reverted;
        try c.transferOwnership(newOwner) { reverted = false; }
        catch { reverted = true; }
        assert(reverted && c.owner() == address(0));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address probeOwner) public payable {
        require(msg.sender != probeOwner);
        address beforeOwner = c.owner();
        require(beforeOwner != address(this));
        bool reverted;
        try c.owned() { reverted = false; } catch { reverted = true; }
        assert(reverted && c.owner() == beforeOwner);
    }
    receive() external payable {}
}
